import { test, expect } from '@playwright/test';

test.describe('Table Summary Row', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/table'); // Replace with the actual URL
  });

  test('should display a summary row at the bottom of the numeric column', async ({ page }) => {
    const summaryRow = await page.getByRole('row', { name: /summary/i });
    expect(await summaryRow.isVisible()).toBe(true);

    const numericColumn = await page.getByRole('columnheader', { name: /numeric column/i });
    const summaryValue = await summaryRow.getByRole('cell', { name: /total/i });

    expect(await summaryValue.innerText()).toBe('100'); // Replace with expected total value
  });

  test('should have correct values in the summary row', async ({ page }) => {
    const summaryRow = await page.getByRole('row', { name: /summary/i });
    const averageValue = await summaryRow.getByRole('cell', { name: /average/i });

    expect(await averageValue.innerText()).toBe('50'); // Replace with expected average value
  });
});
